change.old_schema:
syntax = "proto3";
package simulation.inventory;
message StockItem {
  string sku = 1;
  int32 quantity = 2;
  StockState state = 3;
  repeated string display_labels = 4;
  repeated int32 bin_counts = 6 [packed = false];
  string warehouse = 7;
  string drop_zone = 8;
}

enum StockState {
  STOCK_STATE_UNSPECIFIED = 0;
  STOCK_STATE_QUARANTINED = 1;
}

